function L({to,children,className="",ariaLabel}:{to:string,children:ReactNode,className?:string,ariaLabel?:string}){let ext=to.startsWith("http")||to.startsWith("tel:")||to.startsWith("mailto:")||to.startsWith("sms:");return <a href={to} className={className} aria-label={ariaLabel} onClick={e=>{if(!ext){e.preventDefault();history.pushState({},"",to);dispatchEvent(new PopStateEvent("popstate"))}}}>{children}</a>}
