function Service({s}:{s:typeof S[number]}){return <><Hero title={s.title} ey="Service de transport" img={s.img}><p>{s.intro[0]}</p></Hero><section className="pad"><C><div className="cols"><Title ey="Transport dédié" title="Sans rupture de charge. Sans détour."/><div>{s.intro.map(p=><p key={p}>{p}</p>)}</div></div></C></section><section className="pad dark"><C><Title ey="Nos atouts" title="Une logistique précise, de bout en bout."/><Grid data={s.at}/></C></section><section className="pad"><C><Title ey="Tarifs indicatifs" title="Un prix adapté à la distance et au volume."/><Table/><p className="note">{legal}</p><ZoneLinks/></C></section><CTA/></>}
