function Zones(){return <><Hero title="Zones desservies" ey="France & Europe"><p>Au départ de Mantes-la-Jolie, nous relions l'Île-de-France, la Normandie, toute la France et l'Union européenne.</p></Hero><section className="pad"><C><Map/><div className="zcards">{Z.map(z=><L to={`/zones-desservies/${z.slug}/`} key={z.slug}><small>{z.area} · {z.km}</small><h3>{z.city}</h3><p>{z.veh}</p></L>)}</div><div className="geo-directory"><Title ey="Transport partout en France" title="Livraison express ville par ville."/><p>Consultez nos pages locales pour organiser un transport de marchandises, une livraison urgente ou une course dédiée dans votre ville.</p><div>{GEO.map(g=><L to={`/transport-livraison-marchandises/transporteur-livraison-express-${g.slug}/`} key={g.slug}>{g.city}<A/></L>)}</div></div></C></section><CTA/></>}
function Zone({z}:{z:Z}){return <><Hero title={z.title} ey={`${z.area} · ${z.km}`}><p>{z.intro[0]}</p></Hero><section className="pad"><C><div className="cols"><Title ey="Livraison locale" title={`Votre transporteur à ${z.city}.`}/><div>{z.intro.map(p=><p key={p}>{p}</p>)}</div></div><Grid data={z.pts.map(x=>[x,""])}/></C></section><section className="pad dark"><C><Title ey="Tarifs" title="Tarifs au départ de Mantes-la-Jolie."/><Table full hi={z.zone}/><p className="note">{legal}</p></C></section><CTA/></>}
function GeoFAQ({g}:{g:Geo}){return <section className="pad"><C><Title ey={`FAQ livraison ${g.city}`} title={`Organiser votre transport à ${g.city}.`}/><div className="faq">{geoFaqData(g).map(([q,a],i)=><details key={q}><summary><span>0{i+1}</span>{q}<b>+</b></summary><p>{a}</p></details>)}</div></C></section>}
function GeoPage({g}:{g:Geo}){const url=`/transport-livraison-marchandises/transporteur-livraison-express-${g.slug}/`;const nearby=GEO.filter(x=>x.region===g.region&&x.slug!==g.slug).slice(0,6);return <><Hero title={`Transport et livraison de marchandises à ${g.city}`} ey={`${g.department} · ${g.region}`}><p>Transporteur express à {g.city} pour colis, palettes, mobilier et marchandises, avec véhicule dédié et chauffeur.</p></Hero><section className="pad"><C><div className="cols"><Title ey={`Transporteur à ${g.city}`} title={`Une livraison express, directe et suivie à ${g.city}.`}/><div><p>TransExpress78 organise votre transport de marchandises vers ou depuis {g.city}, dans le {g.department}. Nous prenons en charge les livraisons urgentes, courses professionnelles, palettes, colis volumineux, mobilier et matériel événementiel.</p><p>Depuis notre base de Mantes-la-Jolie, nos chauffeurs rejoignent {g.city} principalement par {g.axis}. Votre chargement voyage dans un véhicule dédié, sans groupage ni rupture de charge, avec confirmation de livraison.</p><p>Particulier, artisan, commerce ou entreprise à {g.city} : demandez un devis clair selon la distance, le volume, le poids et le délai souhaité.</p><p>{REGION_CONTEXT[g.region]}</p></div></div><Grid data={[["Livraison express",`Enlèvement et livraison urgente à ${g.city}, selon disponibilité.`],["Transport dédié","Un seul chargement, un chauffeur et un trajet direct."],["Tous volumes","Break 3m³, Fourgon 10m³ ou Hayon 20m³."],["Suivi de livraison","Confirmation et preuve de dépôt par WhatsApp."]]}/></C></section><section className="pad dark"><C><Title ey="Nos véhicules" title={`Le bon utilitaire pour livrer à ${g.city}.`}/><div className="geo-services"><article><h3>Course urgente et petits colis</h3><p>Le Break 3m³ convient aux plis, pièces détachées, cartons et petits équipements à livrer rapidement à {g.city}.</p></article><article><h3>Palettes et transport professionnel</h3><p>Le Fourgon 10m³ transporte jusqu'à trois palettes Europe, du stock, du mobilier et du matériel professionnel.</p></article><article><h3>Livraison avec hayon</h3><p>Le camion 20m³ avec hayon facilite la manutention des charges lourdes et des marchandises volumineuses.</p></article></div><B to={wa(`Bonjour, je souhaite un devis pour un transport ou une livraison à ${g.city}. Page : https://transexpress78.fr${url}`)}>Devis livraison à {g.city}</B></C></section><section className="pad"><C><Title ey="Tarifs indicatifs" title={`Quel prix pour un transport à ${g.city} ?`}/><Table/><p className="note">{legal}</p>{nearby.length>0&&<div className="nearby"><h3>Transport dans les villes proches</h3><div>{nearby.map(x=><L to={`/transport-livraison-marchandises/transporteur-livraison-express-${x.slug}/`} key={x.slug}>{x.city}<A/></L>)}</div></div>}</C></section><GeoFAQ g={g}/><CTA/></>}
function About(){return <><Hero title="À propos de TransExpress78" ey="Notre entreprise" img="/flotte-break-3m3.webp"/><section className="pad"><C><div className="cols"><Title ey="Notre histoire" title="Sur l'axe A13, au cœur de la vallée de la Seine."/><div><p>TransExpress78 est une entreprise de transport de marchandises basée à Mantes-la-Jolie. Notre implantation nous permet de relier rapidement les Yvelines, Paris et la Normandie, puis toute la France et l'Union européenne.</p><p>Notre flotte de trois gabarits répond à chaque volume sans surdimensionnement : Break 3m³, Fourgon 10m³ et Hayon 20m³. Un chauffeur dédié prend en charge votre marchandise du point d'enlèvement jusqu'à la livraison.</p></div></div><img className="wide" src="/flotte-hayon-20m3.webp" alt="Camion Hayon 20m³ TransExpress78" loading="lazy" decoding="async"/><Title ey="Nos engagements" title="La confiance se mesure à chaque livraison."/><Grid data={[["Ponctualité","Un enlèvement rapide et un horaire annoncé."],["Preuve de livraison WhatsApp","Une photo et une confirmation à chaque dépôt."],["Assurance marchandises","Toutes nos prestations sont couvertes."],["Conseil gratuit","Le véhicule le plus juste pour votre transport."]]}/><div className="nap"><b>TransExpress78</b><p>{ADDR}<br/>{P} · SIRET {SIRET}<br/>Lun – Dim · 7h00 – 20h00</p></div></C></section><CTA/></>}
function Contact(){return <><Hero title="Contactez TransExpress78" ey="Réponse rapide"/><section className="pad"><C><div className="cols"><div><Title ey="Coordonnées" title="Parlons de votre livraison."/><p><b>{P}</b><br/><a href={`mailto:${EMAIL}`}>{EMAIL}</a><br/>{ADDR}<br/>Du lundi au dimanche · 7h–20h</p><B to={wa()}>WhatsApp</B></div><div className="form"><h3>Être rappelé</h3><Form/></div></div><Map/></C></section></>}
function Legal({kind}:{kind:string}){let title=kind==="m"?"Mentions légales":kind==="p"?"Politique de confidentialité":"Conditions générales de vente";return <><Hero title={title} ey="Informations légales"/><section className="pad"><C><article>{kind==="m"?<><h2>Éditeur du site</h2><p><b>TransExpress78</b><br/>{ADDR}<br/>Téléphone : {P}<br/>SIRET : {SIRET}</p><h2>Activité</h2><p>Prestations de transport de marchandises en France et dans l'Union européenne.</p></>:kind==="p"?<><h2>Données collectées</h2><p>Les données de contact saisies dans le formulaire — nom et numéro de téléphone — sont collectées uniquement afin de répondre à votre demande de rappel.</p><h2>Vos droits</h2><p>Conformément au RGPD, vous disposez de droits d'accès, de rectification et de suppression de vos données. Contactez TransExpress78 au {P}.</p></>:<><h2>Prestations et devis</h2><p>Prestations de transport. Devis valable 30 jours. Tarifs HT, TVA 20 % en sus.</p><h2>Paiement</h2><p>Paiement à la livraison pour les particuliers. Facturation mensuelle pour les professionnels.</p><h2>Assurance et droit</h2><p>Assurance marchandises transportées. Droit applicable français.</p></>}</article></C></section></>}
